/** Adds `code` the way a Node error thrown from JS has it: tagged in `toString()` and `stack`, not in `name`. */
export declare const withCode: <E extends Error>(error: E, code: string) => E;
/** Adds `code` the way a Node error thrown from C++ has it: nowhere else. */
export declare const withNativeCode: <E extends Error>(error: E, code: string) => E;
/**
 * @param expected Worded as Node words it, `of type string` or `an instance of Buffer or URL`.
 * @param native Shape the error as Node's C++ throws it.
 */
export declare const invalidArgType: (name: string, expected: string, actual: unknown, native?: boolean) => TypeError;
export declare const invalidArgValue: (name: string, value: unknown, reason?: string) => TypeError;
/** @param native Shape the error as Node's C++ throws it, which also skips digit grouping. */
export declare const outOfRange: (name: string, range: string, value: unknown, native?: boolean) => RangeError;
export declare const invalidThis: (type: string) => TypeError;
export declare const methodNotImplemented: (method: string) => Error;
export declare const invalidUrlScheme: (expected: string) => TypeError;
